//! The synthetic demo sensors (`tests/fixtures/sensors`, our own numbers,
//! generated by `make_demo.py`) that the web app offers as "demo sensors".
//! They double as fixtures for the sensor LDT and SensXML readers.

use eulumdat::sensor::{DetectionVolume, Motion, Quality, SensXml, REFERENCE_DEPTH};
use eulumdat::Eulumdat;

const CEILING: &str = include_str!("fixtures/sensors/demo_ceiling_360.ldt");
const CORRIDOR: &str = include_str!("fixtures/sensors/demo_corridor.ldt");
const SENSXML: &[u8] = include_bytes!("fixtures/sensors/demo_ceiling_sensxml.xml");
const SENSXML_WALL: &[u8] = include_bytes!("fixtures/sensors/demo_wall_180_sensxml.xml");
const SENSXML_HIGHBAY: &[u8] = include_bytes!("fixtures/sensors/demo_highbay_sensxml.xml");
const SENSXML_CORRIDOR: &[u8] = include_bytes!("fixtures/sensors/demo_corridor_sensxml.xml");

fn volume(text: &str) -> DetectionVolume {
    DetectionVolume::new(Eulumdat::parse(text).expect("demo LDT parses"))
}

#[test]
fn ceiling_detector_sphere_sector() {
    // slant range 8.25 m up to 80°: at 2 m below, √(8.25² − 2²) = 8.00 m;
    // radial × 0.5 → √(4.125² − 4) = 3.61 m; presence × 0.35 → 2.08 m
    let v = volume(CEILING);
    let d = REFERENCE_DEPTH;
    let t = v.motion_footprint(Motion::Tangential, d, 1.0).unwrap();
    let r = v.motion_footprint(Motion::Radial, d, 1.0).unwrap();
    let p = v.motion_footprint(Motion::Presence, d, 1.0).unwrap();
    assert!((t.max_range - 8.0).abs() < 0.02, "{}", t.max_range);
    assert!((r.max_range - 3.61).abs() < 0.02, "{}", r.max_range);
    assert!((p.max_range - 2.08).abs() < 0.02, "{}", p.max_range);
    // presence volume ends 2.89 m below the sensor
    assert!(v
        .motion_footprint(Motion::Presence, 3.0, 5.0)
        .unwrap()
        .is_empty());
}

#[test]
fn corridor_detector_is_a_slab() {
    let v = volume(CORRIDOR);
    let fp = v.motion_footprint(Motion::Tangential, 2.0, 1.0).unwrap();
    assert!((fp.reach[0] - 1.25).abs() < 0.05, "across {}", fp.reach[0]);
    assert!((fp.reach[90] - 12.0).abs() < 0.05, "along {}", fp.reach[90]);
    // radial is the same volume, no presence detection
    let r = v.motion_footprint(Motion::Radial, 2.0, 1.0).unwrap();
    assert!((r.max_range - fp.max_range).abs() < 1e-9);
    assert!(v.motion_footprint(Motion::Presence, 2.0, 1.0).is_none());
}

#[test]
fn demo_sensxml() {
    let x = SensXml::parse(SENSXML).expect("demo SensXML parses");
    assert_eq!(
        x.header.product_group.as_deref(),
        Some("Präsenzmelder (Demo)")
    );
    assert_eq!(x.heights(Motion::Tangential), vec![2.5, 3.0, 4.0]);
    assert_eq!(x.heights(Motion::Presence), vec![2.5, 3.0]);
    assert!(x.warnings.is_empty(), "{:?}", x.warnings);
    let (fp, q) = x.footprint(Motion::Tangential, 3.0, true).unwrap();
    assert_eq!(q, Quality::Measured);
    assert!((fp.max_range - 7.0).abs() < 1e-9);
    // Relux view: planning shapes at 2.0 m, scaled below the lowest height
    let (fp, q) = x.footprint(Motion::Radial, 2.0, true).unwrap();
    assert_eq!(q, Quality::Extrapolated);
    assert!((fp.max_range - 2.75 * 2.0 / 2.5).abs() < 1e-9);
}

#[test]
fn demo_wall_detector_sees_only_the_front() {
    let x = SensXml::parse(SENSXML_WALL).unwrap();
    assert_eq!(x.sensor.mounting_type, Some(1));
    assert!(x.source(Motion::Presence).is_none());
    let (fp, _) = x.footprint(Motion::Tangential, 2.5, false).unwrap();
    assert!((fp.reach[0] - 12.0).abs() < 1e-6, "front {}", fp.reach[0]);
    assert!(fp.reach[180] < 1e-6, "behind the wall {}", fp.reach[180]);
    // planning: half circle of 10 m
    let (fp, _) = x.footprint(Motion::Tangential, 2.5, true).unwrap();
    let half = std::f64::consts::PI * 100.0 / 2.0;
    assert!((fp.area_m2 - half).abs() / half < 0.02, "{}", fp.area_m2);
}

#[test]
fn demo_highbay_interpolates_between_heights() {
    let x = SensXml::parse(SENSXML_HIGHBAY).unwrap();
    assert_eq!(x.heights(Motion::Tangential), vec![6.0, 10.0, 14.0]);
    let (fp, q) = x.footprint(Motion::Tangential, 8.0, true).unwrap();
    assert_eq!(q, Quality::Interpolated);
    assert!((fp.max_range - 10.0).abs() < 1e-9, "{}", fp.max_range); // halfway 8 → 12
    let (_, q) = x.footprint(Motion::Presence, 8.0, true).unwrap();
    assert_eq!(q, Quality::Extrapolated); // presence measured at 6 m only
}

#[test]
fn demo_corridor_planning_rectangle() {
    let x = SensXml::parse(SENSXML_CORRIDOR).unwrap();
    let (fp, _) = x.footprint(Motion::Tangential, 2.5, true).unwrap();
    assert!((fp.reach[0] - 10.8).abs() < 1e-6, "{}", fp.reach[0]);
    assert!((fp.reach[90] - 1.8).abs() < 1e-6, "{}", fp.reach[90]);
    assert!((fp.area_m2 - 21.6 * 3.6).abs() < 1.0, "{}", fp.area_m2);
}

/// The landing page quotes this layout (Interior designer, Classroom preset
/// 10 × 8 × 3 m, workplane 0.8 m, demo ceiling detector, automatic
/// placement): keep the text in `landing/src/gen_landing.py` +
/// `landing_tr.json` (`sens_pcap`) in step with these numbers.
#[test]
fn landing_page_classroom_plan() {
    use eulumdat::sensor::coverage::{
        auto_grid_oriented, coverage_with, grid_positions, rotated, CoverageRoom, PlaneAreas,
        DEFAULT_WALL_MARGIN,
    };
    use eulumdat::sensor::en15193::{assess, FoInput, OccupancyControl, SpaceType};
    use eulumdat::sensor::SensorFile;

    let f = SensorFile::from_bytes(CEILING.as_bytes(), "sensor/sensldt").unwrap();
    let room = CoverageRoom {
        length: 10.0,
        width: 8.0,
        mount_height: 3.0,
        walk_plane: 0.0,
        presence_plane: 0.8,
        margin: DEFAULT_WALL_MARGIN,
    };
    let areas = PlaneAreas::new(&f, &room, false);
    let (nx, ny, rot) =
        auto_grid_oriented(&areas, &room, Motion::Presence, 0.95, 100, &[0.0, 90.0]).unwrap();
    assert_eq!((nx, ny, rot), (3, 3, 0.0));
    let cov = coverage_with(
        &areas,
        &room,
        &rotated(grid_positions(10.0, 8.0, 3, 3), rot),
    );
    let pres = cov.get(Motion::Presence).unwrap().covered_fraction;
    assert_eq!(format!("{:.0}", pres * 100.0), "98", "{pres}");
    let fo = assess(&FoInput {
        control: OccupancyControl::AutoOnAutoOff,
        space: SpaceType::Classroom,
        hold_time_ok: true,
        group_m2: cov.m2_per_sensor(),
        m2_per_sensor: cov.m2_per_sensor(),
        coverage: pres,
    });
    assert!(fo.credited);
    let saving = (1.0 - fo.f_o / fo.f_o_manual) * 100.0;
    assert_eq!(format!("{saving:.0}"), "11", "{saving}");
}
